(function() {
    'use strict';

    class OrgRedesignAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Organizational Redesign: Restructuring for Growth';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    icon: '🏢',
                    titleKey: 'r1_briefing_title',
                    descKey: 'r1_briefing_desc'
                },
                {
                    icon: '📐',
                    titleKey: 'r2_briefing_title',
                    descKey: 'r2_briefing_desc'
                },
                {
                    icon: '👥',
                    titleKey: 'r3_briefing_title',
                    descKey: 'r3_briefing_desc'
                },
                {
                    icon: '🎯',
                    titleKey: 'r4_briefing_title',
                    descKey: 'r4_briefing_desc'
                }
            ];

            this.INTEGRATION_EFFECTS = {
                A: { costSynergies: 28, talentRetention: -25, revenueReadiness: 15, culturalIntegration: -15 },
                B: { costSynergies: 8,  talentRetention: 15,  revenueReadiness: 20, culturalIntegration: 10 },
                C: { costSynergies: 18, talentRetention: 5,   revenueReadiness: 35, culturalIntegration: 15 },
                D: { costSynergies: -5, talentRetention: 25,  revenueReadiness: 40, culturalIntegration: -5 }
            };

            this.STRUCTURE_EFFECTS = {
                F: { costSynergies: 10, talentRetention: -10, revenueReadiness: -10, culturalIntegration: -15, coordination: 20 },
                D: { costSynergies: 5,  talentRetention: 10,  revenueReadiness: 10,  culturalIntegration: 5,   coordination: 50 },
                M: { costSynergies: 0,  talentRetention: -5,  revenueReadiness: 15,  culturalIntegration: -10, coordination: 65 },
                N: { costSynergies: -5, talentRetention: 15,  revenueReadiness: 20,  culturalIntegration: 10,  coordination: 75 }
            };

            this.CONSISTENCY_MAP = {
                'A-F': 15, 'A-D': 5,  'A-M': -10, 'A-N': -15,
                'B-F': -15,'B-D': 15, 'B-M': 0,   'B-N': 10,
                'C-F': -10,'C-D': 10, 'C-M': 15,  'C-N': 5,
                'D-F': -20,'D-D': 5,  'D-M': 5,   'D-N': 15
            };

            this.TALENT_INTERVENTIONS = {
                t1: { cost: 1.8, retention: 35, sideEffect: -5 },
                t2: { cost: 0.3, retention: 20, sideEffect: -3 },
                t3: { cost: 0.8, retention: 45, sideEffect: 0 },
                t4: { cost: 0.2, retention: 15, sideEffect: 5 }
            };

            this.CULTURE_INTERVENTIONS = {
                c1: { cost: 0.1, cultural: 12, speed: 'fast' },
                c2: { cost: 0.15, cultural: 18, speed: 'slow' },
                c3: { cost: 0.3, cultural: 15, speed: 'medium' },
                c4: { cost: 0.6, cultural: 22, speed: 'slow' },
                c5: { cost: 0.4, cultural: 10, speed: 'slow' },
                c6: { cost: 0.05, cultural: 8, speed: 'fast' }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    costSynergies: 0,
                    talentRetention: 50,
                    revenueReadiness: 0,
                    culturalIntegration: 0,
                    consistencyScore: 100,
                    budgetRemaining: 4.0,
                    integrationStrategy: '',
                    structureBlueprint: '',
                    financialScore: 0,
                    marketScore: 0,
                    orgScore: 0,
                    learningScore: 0,
                    overallScore: 0,
                    financialHistory: [],
                    marketHistory: [],
                    orgHistory: [],
                    learningHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    integrationChoice: 'C',
                    structureChoice: 'D',
                    talentSelections: '',
                    cultureSelections: '',
                    boardFocus: 'balanced'
                };
            }
            this._updateBriefing(state);
            this._setupBudgetListeners();
        }

        _setupBudgetListeners() {
            var self = this;
            var checks = document.querySelectorAll('.talentCheck, .cultureCheck');
            checks.forEach(function(cb) {
                cb.addEventListener('change', function() {
                    self._updateBudgetDisplay();
                });
            });
        }

        _updateBudgetDisplay() {
            var total = 0;
            var checks = document.querySelectorAll('.talentCheck:checked, .cultureCheck:checked');
            checks.forEach(function(cb) {
                total += parseFloat(cb.value);
            });
            var remaining = 4.0 - total;
            var display = document.getElementById('budgetDisplay');
            if (display) {
                display.textContent = '€' + remaining.toFixed(2) + 'M';
                display.style.color = remaining < 0 ? '#e53e3e' : '#2c5282';
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var iconEl = document.getElementById('briefingIcon');
            if (iconEl) iconEl.textContent = round.icon;

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl && window.mySimulation) {
                titleEl.textContent = window.mySimulation.t(round.titleKey);
            }

            var textEl = document.getElementById('briefingText');
            if (textEl && window.mySimulation) {
                textEl.innerHTML = window.mySimulation.t(round.descKey);
            }

            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            panels.forEach(function(pid, i) {
                var el = document.getElementById(pid);
                if (el) el.style.display = (i === idx) ? 'block' : 'none';
            });

            var eventAlert = document.getElementById('eventAlert');
            var eventText = document.getElementById('eventText');
            if (eventAlert && eventText && window.mySimulation) {
                if (idx === 1 && state.domainState && state.domainState.integrationStrategy === 'A') {
                    eventAlert.style.display = 'flex';
                    eventText.textContent = window.mySimulation.t('event_r2_absorption');
                } else if (idx === 2 && state.domainState && state.domainState.structureBlueprint === 'F') {
                    eventAlert.style.display = 'flex';
                    eventText.textContent = window.mySimulation.t('event_r3_functional');
                } else if (idx === 3) {
                    eventAlert.style.display = 'flex';
                    eventText.textContent = window.mySimulation.t('event_r4_board');
                } else {
                    eventAlert.style.display = 'none';
                }
            }

            if (idx === 3 && state.domainState) {
                var summary = document.getElementById('boardSummary');
                if (summary && window.mySimulation) {
                    var ds = state.domainState;
                    var stratLabel = {A: 'Full Absorption', B: 'Preservation', C: 'Symbiotic', D: 'Apex Leads'}[ds.integrationStrategy] || '—';
                    var structLabel = {F: 'Functional', D: 'Divisional', M: 'Matrix', N: 'Network'}[ds.structureBlueprint] || '—';
                    summary.innerHTML = '<strong>' + window.mySimulation.t('board_summary_label') + '</strong><br>'
                        + window.mySimulation.t('board_strategy') + ': ' + stratLabel + '<br>'
                        + window.mySimulation.t('board_structure') + ': ' + structLabel + '<br>'
                        + window.mySimulation.t('board_synergies') + ': €' + ds.costSynergies + 'M<br>'
                        + window.mySimulation.t('board_retention') + ': ' + Math.round(ds.talentRetention) + '%<br>'
                        + window.mySimulation.t('board_culture') + ': ' + Math.round(ds.culturalIntegration) + '%';
                }
            }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var checked = document.querySelector('input[name="integrationChoice"]:checked');
                if (!checked) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('select_integration_warning'), 'warning'
                    );
                    return false;
                }
                decisions.integrationChoice = checked.value;
            } else if (period === 2) {
                var checked2 = document.querySelector('input[name="structureChoice"]:checked');
                if (!checked2) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('select_structure_warning'), 'warning'
                    );
                    return false;
                }
                decisions.structureChoice = checked2.value;
            } else if (period === 3) {
                var talentChecks = document.querySelectorAll('.talentCheck:checked');
                var cultureChecks = document.querySelectorAll('.cultureCheck:checked');
                var totalCost = 0;
                var tIds = [];
                var cIds = [];
                talentChecks.forEach(function(cb) {
                    totalCost += parseFloat(cb.value);
                    tIds.push(cb.id);
                });
                cultureChecks.forEach(function(cb) {
                    totalCost += parseFloat(cb.value);
                    cIds.push(cb.id);
                });
                if (totalCost > 4.05) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_exceeded_warning'), 'warning'
                    );
                    return false;
                }
                decisions.talentSelections = tIds.join(',');
                decisions.cultureSelections = cIds.join(',');
            } else if (period === 4) {
                var checked4 = document.querySelector('input[name="boardFocus"]:checked');
                if (checked4) decisions.boardFocus = checked4.value;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var ds = state.domainState;
            var d = state.decisions;
            var results = { period: period };

            if (period === 1) {
                var effects = this.INTEGRATION_EFFECTS[d.integrationChoice];
                ds.integrationStrategy = d.integrationChoice;
                ds.costSynergies += effects.costSynergies;
                ds.talentRetention = Math.max(0, Math.min(100, ds.talentRetention + effects.talentRetention));
                ds.revenueReadiness = Math.max(0, Math.min(100, ds.revenueReadiness + effects.revenueReadiness));
                ds.culturalIntegration = Math.max(-30, Math.min(100, ds.culturalIntegration + effects.culturalIntegration));

                ds.financialScore = Math.min(100, Math.max(0, (ds.costSynergies / 40) * 100));
                ds.marketScore = Math.min(100, Math.max(0, ds.revenueReadiness));
                ds.orgScore = Math.min(100, Math.max(0, ds.consistencyScore));
                ds.learningScore = Math.min(100, Math.max(0, (ds.talentRetention + Math.max(0, ds.culturalIntegration)) / 2));

                results.strategyChosen = d.integrationChoice;
                results.costSynergies = ds.costSynergies;
                results.talentRetention = Math.round(ds.talentRetention);
                results.revenueReadiness = Math.round(ds.revenueReadiness);

            } else if (period === 2) {
                var sEffects = this.STRUCTURE_EFFECTS[d.structureChoice];
                var cKey = ds.integrationStrategy + '-' + d.structureChoice;
                var cBonus = this.CONSISTENCY_MAP[cKey] || 0;

                ds.structureBlueprint = d.structureChoice;
                ds.costSynergies += sEffects.costSynergies;
                ds.talentRetention = Math.max(0, Math.min(100, ds.talentRetention + sEffects.talentRetention));
                ds.revenueReadiness = Math.max(0, Math.min(100, ds.revenueReadiness + sEffects.revenueReadiness));
                ds.culturalIntegration = Math.max(-30, Math.min(100, ds.culturalIntegration + sEffects.culturalIntegration));
                ds.consistencyScore = Math.max(0, Math.min(100, ds.consistencyScore + cBonus));

                ds.financialScore = Math.min(100, Math.max(0, (ds.costSynergies / 40) * 100));
                ds.marketScore = Math.min(100, Math.max(0, (ds.revenueReadiness + sEffects.coordination) / 2));
                ds.orgScore = Math.min(100, Math.max(0, ds.consistencyScore));
                ds.learningScore = Math.min(100, Math.max(0, (ds.talentRetention + Math.max(0, ds.culturalIntegration)) / 2));

                results.structureChosen = d.structureChoice;
                results.consistencyBonus = cBonus;
                results.costSynergies = ds.costSynergies;
                results.talentRetention = Math.round(ds.talentRetention);

            } else if (period === 3) {
                var tSel = d.talentSelections ? d.talentSelections.split(',') : [];
                var cSel = d.cultureSelections ? d.cultureSelections.split(',') : [];
                var spent = 0;
                var retentionBoost = 0;
                var culturalBoost = 0;

                var self = this;
                tSel.forEach(function(tid) {
                    var t = self.TALENT_INTERVENTIONS[tid];
                    if (t) {
                        spent += t.cost;
                        retentionBoost += t.retention;
                        ds.culturalIntegration += t.sideEffect;
                    }
                });

                cSel.forEach(function(cid) {
                    var c = self.CULTURE_INTERVENTIONS[cid];
                    if (c) {
                        spent += c.cost;
                        culturalBoost += c.cultural;
                    }
                });

                if (tSel.length === 0 && cSel.length === 0) {
                    ds.talentRetention = Math.max(0, ds.talentRetention - 25);
                }

                ds.talentRetention = Math.max(0, Math.min(100, ds.talentRetention + retentionBoost * 0.4));
                ds.culturalIntegration = Math.max(-30, Math.min(100, ds.culturalIntegration + culturalBoost));
                ds.budgetRemaining = Math.max(0, 4.0 - spent);

                if (ds.structureBlueprint === 'F' && tSel.length < 2) {
                    ds.talentRetention = Math.max(0, ds.talentRetention - 15);
                }

                ds.financialScore = Math.min(100, Math.max(0, (ds.costSynergies / 40) * 100 + (ds.budgetRemaining / 4) * 10));
                ds.marketScore = Math.min(100, Math.max(0, ds.revenueReadiness + ds.talentRetention * 0.2));
                ds.orgScore = Math.min(100, Math.max(0, ds.consistencyScore));
                ds.learningScore = Math.min(100, Math.max(0, (ds.talentRetention + Math.max(0, ds.culturalIntegration)) / 2));

                results.budgetSpent = spent;
                results.retentionBoost = Math.round(retentionBoost * 0.4);
                results.culturalBoost = culturalBoost;
                results.talentRetention = Math.round(ds.talentRetention);
                results.costSynergies = ds.costSynergies;

            } else if (period === 4) {
                var focusEffects = {
                    financial: { financial: 15, market: -5, org: 5, learning: -10 },
                    talent:    { financial: -5, market: 10, org: 0, learning: 15 },
                    balanced:  { financial: 5,  market: 5,  org: 5, learning: 5 }
                };
                var fe = focusEffects[d.boardFocus] || focusEffects.balanced;

                ds.financialScore = Math.min(100, Math.max(0, ds.financialScore + fe.financial));
                ds.marketScore = Math.min(100, Math.max(0, ds.marketScore + fe.market));
                ds.orgScore = Math.min(100, Math.max(0, ds.orgScore + fe.org));
                ds.learningScore = Math.min(100, Math.max(0, ds.learningScore + fe.learning));

                ds.overallScore = Math.round(
                    ds.financialScore * 0.30 +
                    ds.marketScore * 0.25 +
                    ds.orgScore * 0.25 +
                    ds.learningScore * 0.20
                );

                results.boardFocus = d.boardFocus;
                results.financialScore = Math.round(ds.financialScore);
                results.marketScore = Math.round(ds.marketScore);
                results.orgScore = Math.round(ds.orgScore);
                results.learningScore = Math.round(ds.learningScore);
                results.overallScore = ds.overallScore;
                results.costSynergies = ds.costSynergies;
                results.talentRetention = Math.round(ds.talentRetention);
            }

            ds.financialHistory.push(Math.round(ds.financialScore));
            ds.marketHistory.push(Math.round(ds.marketScore));
            ds.orgHistory.push(Math.round(ds.orgScore));
            ds.learningHistory.push(Math.round(ds.learningScore));

            // v1.1.0 fix: persist composite where Express reporting reads it.
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            ds.score = ds.overallScore;
            if (!ds.performance || typeof ds.performance !== 'object') ds.performance = {};
            ds.performance.overallScore = ds.overallScore;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return results;
        }

